<template>
  <div class="service-overview-detail">
    <!-- Suite breakdown: one line per Allure project -->
    <div class="detail-block">
      <div class="detail-block__title">
        <q-icon name="account_tree" size="16px" />
        <span>Test suites ({{ row.suitesWithData }}/{{ row.suites.length }} reporting)</span>
      </div>

      <table class="suite-table">
        <thead>
          <tr>
            <th class="text-left">Suite</th>
            <th class="text-left">Allure project</th>
            <th class="text-right">Total</th>
            <th class="text-right">Failed</th>
            <th class="text-right">Skipped</th>
            <th class="text-right">Pass rate</th>
            <th class="text-left">Last run</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          <tr
            v-for="suiteStat in row.suites"
            :key="suiteStat.name"
            :class="{ 'suite-row--no-data': !suiteStat.hasData }"
          >
            <td>
              <q-icon
                :name="suiteIcon(suiteStat)"
                :class="suiteIconClass(suiteStat)"
                size="14px"
                class="q-mr-xs"
              />
              {{ suiteStat.displayName }}
            </td>
            <td class="mono text-muted">{{ suiteStat.projectId }}</td>

            <template v-if="suiteStat.hasData">
              <td class="text-right">{{ formatNumber(suiteStat.totalTests) }}</td>
              <td class="text-right">
                <span :class="suiteStat.failedTests > 0 ? 'value-bad' : 'text-muted'">
                  {{ formatNumber(suiteStat.failedTests) }}
                </span>
              </td>
              <td class="text-right text-muted">{{ formatNumber(suiteStat.skippedTests) }}</td>
              <td class="text-right">{{ suitePassRate(suiteStat) }}%</td>
              <td class="text-muted">{{ formatDateTime(suiteStat.lastRunAt) }}</td>
            </template>
            <template v-else>
              <td colspan="5" class="text-muted">No report uploaded for this environment</td>
            </template>

            <td class="text-right">
              <q-btn
                flat
                dense
                round
                size="sm"
                icon="open_in_new"
                :href="suiteStat.allureUrl"
                target="_blank"
                rel="noopener"
              >
                <q-tooltip>Open in Allure</q-tooltip>
              </q-btn>
            </td>
          </tr>
        </tbody>
      </table>
    </div>

    <!-- Severity distribution -->
    <div class="detail-block">
      <div class="detail-block__title">
        <q-icon name="bolt" size="16px" />
        <span>Severity distribution</span>
      </div>

      <div v-if="row.severityState === 'loading'" class="text-muted row items-center q-gutter-sm">
        <q-spinner size="16px" />
        <span>Reading severity labels from Allure…</span>
      </div>
      <div v-else-if="row.severityState !== 'loaded'" class="text-muted">
        Severity labels unavailable for this service.
      </div>
      <div v-else class="severity-list">
        <div
          v-for="entry in severityRows"
          :key="entry.severity"
          class="severity-list__item"
        >
          <div class="severity-list__label">
            <span :class="['severity-dot', `severity-dot--${entry.severity}`]"></span>
            {{ entry.label }}
          </div>
          <div class="severity-list__bar">
            <div
              class="severity-list__bar-fill severity-list__bar-fill--passed"
              :style="{ width: barWidth(entry.counts.passed, entry.counts.total) }"
            ></div>
            <div
              class="severity-list__bar-fill severity-list__bar-fill--failed"
              :style="{ width: barWidth(entry.counts.failed, entry.counts.total) }"
            ></div>
            <div
              class="severity-list__bar-fill severity-list__bar-fill--skipped"
              :style="{ width: barWidth(entry.counts.skipped, entry.counts.total) }"
            ></div>
          </div>
          <div class="severity-list__counts">
            <span class="text-muted">{{ formatNumber(entry.counts.total) }} tests</span>
            <span v-if="entry.counts.failed > 0" class="value-bad text-weight-bold">
              {{ formatNumber(entry.counts.failed) }} failed
            </span>
            <span v-else class="value-good">all green</span>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { date } from 'quasar';
import { ALLURE_SEVERITIES, type AllureSeverity, type SeverityStatusCounts } from 'src/services/allure';
import {
  computePassRate,
  type ServiceOverviewRow,
  type ServiceSuiteStat,
} from 'src/services/tests';

const SEVERITY_LABELS: Record<AllureSeverity, string> = {
  blocker: 'Blocker',
  critical: 'Critical',
  normal: 'Normal',
  minor: 'Minor',
  trivial: 'Trivial',
  unknown: 'Unlabeled',
};

export default defineComponent({
  name: 'ServiceOverviewDetail',

  props: {
    row: {
      type: Object as () => ServiceOverviewRow,
      required: true,
    },
  },

  computed: {
    /** Severity buckets that actually have tests, most severe first. */
    severityRows(): { severity: AllureSeverity; label: string; counts: SeverityStatusCounts }[] {
      return ALLURE_SEVERITIES.filter(
        (severity) => this.row.bySeverity[severity].total > 0
      ).map((severity) => ({
        severity,
        label: SEVERITY_LABELS[severity],
        counts: this.row.bySeverity[severity],
      }));
    },
  },

  methods: {
    formatNumber(value: number): string {
      return value.toLocaleString();
    },

    formatDateTime(value: Date | null): string {
      return value ? date.formatDate(value, 'MMM D, HH:mm') : '—';
    },

    suitePassRate(suiteStat: ServiceSuiteStat): string {
      return computePassRate(suiteStat.passedTests, suiteStat.failedTests).toFixed(1);
    },

    suiteIcon(suiteStat: ServiceSuiteStat): string {
      if (!suiteStat.hasData) return 'remove_circle_outline';
      return suiteStat.failedTests > 0 ? 'error' : 'check_circle';
    },

    suiteIconClass(suiteStat: ServiceSuiteStat): string {
      if (!suiteStat.hasData) return 'text-muted';
      return suiteStat.failedTests > 0 ? 'value-bad' : 'value-good';
    },

    barWidth(value: number, total: number): string {
      if (total <= 0) return '0%';
      return `${(value / total) * 100}%`;
    },
  },
});
</script>

