<template>
  <q-page class="tests-overview-page q-pa-md">
    <!-- ══ Header ══ -->
    <div class="row items-start justify-between q-col-gutter-md q-mb-md">
      <div class="col-12 col-md">
        <div class="row items-center q-gutter-sm">
          <h4 class="page-title q-my-none">Test Results</h4>
          <q-chip
            :style="{ background: environmentColor, color: '#fff' }"
            size="sm"
            class="text-weight-bold"
            dense
          >
            {{ currentEnvironment.toUpperCase() }}
          </q-chip>
        </div>
        <div class="page-subtitle">
          Critical-test health per service, sourced from Allure
          <template v-if="lastFetchedAt">
            · updated {{ formatDateTime(lastFetchedAt) }}
          </template>
        </div>
      </div>

      <div class="col-12 col-md-auto row items-center q-gutter-sm justify-end">
        <q-btn
          outline
          no-caps
          dense
          icon="bolt"
          label="Critical gate"
          class="q-px-sm"
          to="/tests/critical-status"
        />
        <q-btn
          outline
          no-caps
          dense
          icon="insights"
          label="Statistics"
          class="q-px-sm"
          to="/tests/statistics-dashboard"
        />
        <q-btn
          outline
          no-caps
          dense
          icon="grid_view"
          label="Card view"
          class="q-px-sm"
          to="/tests"
        />
        <q-btn
          unelevated
          no-caps
          dense
          color="primary"
          icon="refresh"
          label="Refresh"
          class="q-px-sm"
          :loading="loading"
          @click="fetchAll"
        />
      </div>
    </div>

    <!-- ══ KPI strip ══ -->
    <div class="kpi-strip q-mb-md">
      <div :class="['kpi-tile', { 'kpi-tile--alarm': totals.criticalFailed > 0 }]">
        <div class="kpi-tile__label">
          <q-icon name="bolt" size="14px" />
          Critical failures
        </div>
        <div class="kpi-tile__value">
          <span v-if="loading" class="kpi-tile__pending">—</span>
          <template v-else>
            <span class="pulse-dot" v-if="totals.criticalFailed > 0"></span>
            {{ formatNumber(totals.criticalFailed) }}
          </template>
        </div>
        <div class="kpi-tile__foot">
          of {{ formatNumber(totals.criticalTests) }} critical tests
          <span v-if="!totals.severityComplete && !loading"> · still loading</span>
        </div>
      </div>

      <div :class="['kpi-tile', { 'kpi-tile--warn': totals.failingServices > 0 }]">
        <div class="kpi-tile__label">
          <q-icon name="dns" size="14px" />
          Services failing
        </div>
        <div class="kpi-tile__value">{{ totals.failingServices }}</div>
        <div class="kpi-tile__foot">
          of {{ totals.servicesWithData }} reporting ({{ totals.services }} tracked)
        </div>
      </div>

      <div class="kpi-tile">
        <div class="kpi-tile__label">
          <q-icon name="close" size="14px" />
          Failed tests
        </div>
        <div class="kpi-tile__value">{{ formatNumber(totals.failedTests) }}</div>
        <div class="kpi-tile__foot">of {{ formatNumber(totals.totalTests) }} tests</div>
      </div>

      <div class="kpi-tile">
        <div class="kpi-tile__label">
          <q-icon name="check_circle" size="14px" />
          Pass rate
        </div>
        <div class="kpi-tile__value">{{ totals.passRate.toFixed(1) }}%</div>
        <div class="kpi-tile__foot">
          {{ formatNumber(totals.skippedTests) }} skipped (excluded)
        </div>
      </div>
    </div>

    <!-- ══ Critical failure callout ══ -->
    <div v-if="criticalServices.length > 0" class="critical-callout q-mb-md">
      <q-icon name="warning" size="20px" class="critical-callout__icon" />
      <div class="critical-callout__body">
        <div class="critical-callout__title">
          {{ formatNumber(totals.criticalFailed) }} critical
          {{ totals.criticalFailed === 1 ? 'test is' : 'tests are' }} failing across
          {{ criticalServices.length }}
          {{ criticalServices.length === 1 ? 'service' : 'services' }}
        </div>
        <div class="critical-callout__chips">
          <button
            v-for="row in criticalServices"
            :key="row.service"
            type="button"
            class="critical-chip"
            @click="focusService(row)"
          >
            {{ row.displayName }}
            <strong>{{ formatNumber(row.criticalFailed) }}</strong>
          </button>
        </div>
      </div>
    </div>

    <!-- ══ Error banner ══ -->
    <q-banner v-if="error" class="bg-negative text-white q-mb-md" rounded dense>
      <template #avatar>
        <q-icon name="error" />
      </template>
      {{ error }}
      <template #action>
        <q-btn flat no-caps dense label="Retry" @click="fetchAll" />
      </template>
    </q-banner>

    <!-- ══ Toolbar ══ -->
    <div class="tests-toolbar q-mb-sm">
      <q-input
        v-model="search"
        dense
        outlined
        clearable
        debounce="200"
        placeholder="Search service…"
        class="tests-toolbar__search"
      >
        <template #prepend>
          <q-icon name="search" size="18px" />
        </template>
      </q-input>

      <q-select
        v-model="groupFilter"
        :options="groupOptions"
        dense
        outlined
        multiple
        clearable
        emit-value
        map-options
        options-dense
        placeholder="All groups"
        label="Group"
        class="tests-toolbar__select"
      />

      <q-btn-toggle
        v-model="statusFilter"
        no-caps
        dense
        unelevated
        toggle-color="primary"
        color="grey-3"
        text-color="grey-8"
        :options="statusFilterOptions"
      />

      <q-space />

      <div class="tests-toolbar__count">
        {{ filteredRows.length }} / {{ rows.length }} services
      </div>
    </div>

    <!-- ══ Table ══ -->
    <q-table
      v-model:pagination="pagination"
      :rows="filteredRows"
      :columns="columns"
      row-key="service"
      flat
      bordered
      dense
      :loading="loading"
      :wrap-cells="false"
      :rows-per-page-options="[10, 25, 50, 0]"
      class="overview-table"
    >
      <template #loading>
        <q-inner-loading showing color="primary" />
      </template>

      <template #no-data>
        <div class="full-width row flex-center q-py-lg text-muted">
          <q-icon name="search_off" size="20px" class="q-mr-sm" />
          No service matches the current filters
        </div>
      </template>

      <template #body="props">
        <q-tr
          :props="props"
          :class="rowClass(props.row)"
          class="cursor-pointer"
          @click="toggleExpanded(props.row)"
        >
          <q-td
            v-for="col in props.cols"
            :key="col.name"
            :props="props"
            :class="cellClass(col.name, props.row)"
          >
            <!-- Service -->
            <template v-if="col.name === 'service'">
              <div class="service-cell">
                <q-icon
                  :name="expandedService === props.row.service ? 'expand_more' : 'chevron_right'"
                  size="18px"
                  class="service-cell__chevron"
                />
                <div class="service-cell__text">
                  <div class="service-cell__name">{{ props.row.displayName }}</div>
                  <div class="service-cell__group">
                    <q-icon :name="props.row.groupIcon" size="11px" />
                    {{ props.row.groupDisplayName }}
                    · {{ props.row.suitesWithData }}/{{ props.row.suites.length }} suites
                  </div>
                </div>
              </div>
            </template>

            <!-- Status -->
            <template v-else-if="col.name === 'status'">
              <span :class="['status-pill', `status-pill--${statusOf(props.row)}`]">
                <q-icon :name="statusIcon(props.row)" size="13px" />
                {{ statusLabel(props.row) }}
              </span>
            </template>

            <!-- Critical total -->
            <template v-else-if="col.name === 'criticalTests'">
              <template v-if="props.row.severityState === 'loaded'">
                <span v-if="props.row.criticalTests > 0" class="value-strong">
                  {{ formatNumber(props.row.criticalTests) }}
                </span>
                <span v-else class="text-muted">none tagged</span>
                <q-tooltip v-if="props.row.blockerTests > 0" anchor="top middle" self="bottom middle">
                  Includes {{ formatNumber(props.row.blockerTests) }} blocker-severity tests
                </q-tooltip>
              </template>
              <q-spinner v-else-if="props.row.severityState === 'loading'" size="14px" />
              <span v-else-if="props.row.severityState === 'error'" class="text-muted">n/a</span>
              <span v-else class="text-muted">…</span>
            </template>

            <!-- Critical failed — the headline number -->
            <template v-else-if="col.name === 'criticalFailed'">
              <template v-if="props.row.severityState === 'loaded'">
                <span v-if="props.row.criticalFailed > 0" class="critical-badge">
                  <span class="pulse-dot"></span>
                  {{ formatNumber(props.row.criticalFailed) }}
                  <q-tooltip anchor="top middle" self="bottom middle">
                    {{ formatNumber(props.row.criticalFailed) }} of
                    {{ formatNumber(props.row.criticalTests) }} critical tests failing
                    <template v-if="props.row.blockerFailed > 0">
                      ({{ formatNumber(props.row.blockerFailed) }} blocker)
                    </template>
                  </q-tooltip>
                </span>
                <span v-else-if="props.row.criticalTests > 0" class="value-good">
                  <q-icon name="check" size="14px" /> 0
                </span>
                <span v-else class="text-muted">—</span>
              </template>
              <q-spinner v-else-if="props.row.severityState === 'loading'" size="14px" />
              <span v-else-if="props.row.severityState === 'error'" class="text-muted">—</span>
              <span v-else class="text-muted">…</span>
            </template>

            <!-- Total tests -->
            <template v-else-if="col.name === 'totalTests'">
              <span v-if="props.row.hasData">{{ formatNumber(props.row.totalTests) }}</span>
              <span v-else class="text-muted">—</span>
            </template>

            <!-- Failed (all severities) -->
            <template v-else-if="col.name === 'failedTests'">
              <span v-if="!props.row.hasData" class="text-muted">—</span>
              <span v-else-if="props.row.failedTests > 0" class="value-bad text-weight-bold">
                {{ formatNumber(props.row.failedTests) }}
              </span>
              <span v-else class="text-muted">0</span>
            </template>

            <!-- Skipped -->
            <template v-else-if="col.name === 'skippedTests'">
              <span :class="skippedClass(props.row)">
                {{ props.row.hasData ? formatNumber(props.row.skippedTests) : '—' }}
                <q-tooltip
                  v-if="skippedClass(props.row) === 'value-warn'"
                  anchor="top middle"
                  self="bottom middle"
                >
                  {{ skippedShare(props.row).toFixed(0) }}% of this service's tests never ran
                </q-tooltip>
              </span>
            </template>

            <!-- Pass rate -->
            <template v-else-if="col.name === 'passRate'">
              <div v-if="props.row.hasData" class="passrate-cell">
                <div class="passrate-cell__track">
                  <div
                    class="passrate-cell__fill"
                    :style="{
                      width: `${props.row.passRate}%`,
                      background: passRateColor(props.row.passRate),
                    }"
                  ></div>
                </div>
                <span class="passrate-cell__value">{{ props.row.passRate.toFixed(1) }}%</span>
              </div>
              <span v-else class="text-muted">—</span>
            </template>

            <!-- Duration -->
            <template v-else-if="col.name === 'durationMs'">
              <span :class="props.row.hasData ? '' : 'text-muted'">
                {{ props.row.hasData ? formatDuration(props.row.durationMs) : '—' }}
              </span>
            </template>

            <!-- Last run -->
            <template v-else-if="col.name === 'lastRunAt'">
              <span :class="stalenessClass(props.row.lastRunAt)">
                {{ formatRelative(props.row.lastRunAt) }}
                <q-tooltip v-if="props.row.lastRunAt" anchor="top middle" self="bottom middle">
                  {{ formatDateTime(props.row.lastRunAt) }}
                </q-tooltip>
              </span>
            </template>

            <!-- Actions -->
            <template v-else-if="col.name === 'actions'">
              <div class="row no-wrap items-center justify-end" @click.stop>
                <q-btn
                  flat
                  dense
                  round
                  size="sm"
                  icon="chevron_right"
                  @click="navigateToDetails(props.row.service)"
                >
                  <q-tooltip>Open service details</q-tooltip>
                </q-btn>
                <q-btn
                  v-if="props.row.suites.length > 0"
                  flat
                  dense
                  round
                  size="sm"
                  icon="open_in_new"
                  :href="props.row.suites[0].allureUrl"
                  target="_blank"
                  rel="noopener"
                >
                  <q-tooltip>Open in Allure</q-tooltip>
                </q-btn>
              </div>
            </template>

            <template v-else>{{ col.value }}</template>
          </q-td>
        </q-tr>

        <!-- Expanded detail row -->
        <q-tr v-if="expandedService === props.row.service" :props="props" class="detail-tr">
          <q-td :colspan="props.cols.length" class="detail-td">
            <ServiceOverviewDetail :row="props.row" />
          </q-td>
        </q-tr>
      </template>
    </q-table>
  </q-page>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { date } from 'quasar';
import type { QTableColumn } from 'quasar';
import { getCurrentEnvironment } from 'src/pages/APIs';
import {
  SERVICE_GROUPS,
  computeTotals,
  testsOverviewAggregatorService,
  type OverviewTotals,
  type ServiceOverviewRow,
} from 'src/services/tests';
import { logger } from 'src/utils/logger';
import ServiceOverviewDetail from './Components/ServiceOverviewDetail.vue';

type StatusFilter = 'all' | 'critical' | 'failing' | 'nodata';

/**
 * How many services fetch their severity breakdown at once. status-chart.json
 * is a large payload (up to a few MB per Allure project), so this keeps the
 * network from being saturated while rows fill in progressively.
 */
const SEVERITY_CONCURRENCY = 4;

/** A test run older than this is flagged as stale in the Last run column. */
const STALE_RUN_HOURS = 24;

/** Percentage of skipped tests above which the Skipped column is highlighted. */
const SKIPPED_WARN_SHARE = 10;

export default defineComponent({
  name: 'TestsOverviewPage',

  components: { ServiceOverviewDetail },

  data() {
    return {
      rows: [] as ServiceOverviewRow[],
      loading: false,
      error: null as string | null,
      lastFetchedAt: null as Date | null,
      search: '' as string | null,
      groupFilter: [] as string[] | null,
      statusFilter: 'all' as StatusFilter,
      expandedService: null as string | null,
      pagination: { rowsPerPage: 25, sortBy: 'criticalFailed', descending: true },
      /** Guards against a stale severity load writing into a newer row set */
      loadToken: 0,
    };
  },

  computed: {
    currentEnvironment(): string {
      const env = getCurrentEnvironment();
      return env === 'local' ? 'dev' : env;
    },

    environmentColor(): string {
      const colorMap: Record<string, string> = {
        dev: '#2563eb',
        stage: '#f59e0b',
        prod: '#dc2626',
        demo: '#9333ea',
        sandbox: '#0d9488',
      };
      return colorMap[this.currentEnvironment] || '#64748b';
    },

    columns(): QTableColumn<ServiceOverviewRow>[] {
      return [
        {
          name: 'service',
          label: 'Service',
          field: 'displayName',
          align: 'left',
          sortable: true,
        },
        {
          name: 'status',
          label: 'Status',
          field: (row) => this.statusRank(row),
          align: 'left',
          sortable: true,
        },
        {
          name: 'criticalTests',
          label: 'Critical tests',
          field: 'criticalTests',
          align: 'right',
          sortable: true,
        },
        {
          name: 'criticalFailed',
          label: 'Critical failed',
          field: 'criticalFailed',
          align: 'right',
          sortable: true,
        },
        {
          name: 'totalTests',
          label: 'Total tests',
          field: 'totalTests',
          align: 'right',
          sortable: true,
        },
        {
          name: 'failedTests',
          label: 'Failed',
          field: 'failedTests',
          align: 'right',
          sortable: true,
        },
        {
          name: 'skippedTests',
          label: 'Skipped',
          field: 'skippedTests',
          align: 'right',
          sortable: true,
        },
        {
          name: 'passRate',
          label: 'Pass rate',
          field: 'passRate',
          align: 'left',
          sortable: true,
        },
        {
          name: 'durationMs',
          label: 'Duration',
          field: 'durationMs',
          align: 'right',
          sortable: true,
        },
        {
          name: 'lastRunAt',
          label: 'Last run',
          field: (row) => (row.lastRunAt ? row.lastRunAt.getTime() : 0),
          align: 'left',
          sortable: true,
        },
        {
          name: 'actions',
          label: '',
          field: 'service',
          align: 'right',
          sortable: false,
        },
      ];
    },

    groupOptions(): { label: string; value: string }[] {
      return SERVICE_GROUPS.map((group) => ({
        label: group.displayName,
        value: group.name,
      }));
    },

    statusFilterOptions(): { label: string; value: StatusFilter }[] {
      return [
        { label: 'All', value: 'all' },
        { label: 'Critical only', value: 'critical' },
        { label: 'Failing', value: 'failing' },
        { label: 'No data', value: 'nodata' },
      ];
    },

    filteredRows(): ServiceOverviewRow[] {
      const term = (this.search || '').trim().toLowerCase();
      const groups = this.groupFilter || [];

      return this.rows.filter((row) => {
        if (term && !`${row.displayName} ${row.service}`.toLowerCase().includes(term)) {
          return false;
        }
        if (groups.length > 0 && !groups.includes(row.group)) {
          return false;
        }
        if (this.statusFilter === 'critical') return row.criticalFailed > 0;
        if (this.statusFilter === 'failing') return row.hasData && row.failedTests > 0;
        if (this.statusFilter === 'nodata') return !row.hasData;
        return true;
      });
    },

    /** Totals reflect the current filter so the KPI strip matches the table. */
    totals(): OverviewTotals {
      return computeTotals(this.filteredRows);
    },

    criticalServices(): ServiceOverviewRow[] {
      return this.rows
        .filter((row) => row.criticalFailed > 0)
        .sort((a, b) => b.criticalFailed - a.criticalFailed);
    },
  },

  mounted() {
    this.fetchAll();
  },

  methods: {
    async fetchAll(): Promise<void> {
      this.loading = true;
      this.error = null;
      const token = ++this.loadToken;

      try {
        const rows = await testsOverviewAggregatorService.getServiceRows(
          this.currentEnvironment
        );
        if (token !== this.loadToken) return;

        this.rows = rows;
        this.lastFetchedAt = new Date();
        this.loading = false;

        // Severity data is heavy — stream it in behind the already-rendered table
        void this.loadSeverityData(token);
      } catch (err) {
        logger.error('[TestsOverviewPage] Failed to load test results:', err);
        if (token !== this.loadToken) return;
        this.error = 'Failed to load test results from Allure. Please try again.';
        this.loading = false;
      }
    },

    /** Fan out severity requests with a bounded number of parallel workers. */
    async loadSeverityData(token: number): Promise<void> {
      const queue = this.rows.filter((row) => row.hasData);
      this.rows
        .filter((row) => !row.hasData)
        .forEach((row) => {
          row.severityState = 'error';
        });

      const worker = async (): Promise<void> => {
        while (queue.length > 0 && token === this.loadToken) {
          const row = queue.shift();
          if (!row) return;
          await this.loadSeverityForRow(row, token);
        }
      };

      await Promise.all(
        Array.from({ length: SEVERITY_CONCURRENCY }, () => worker())
      );
    },

    async loadSeverityForRow(row: ServiceOverviewRow, token: number): Promise<void> {
      row.severityState = 'loading';
      try {
        const result = await testsOverviewAggregatorService.getSeverityForService(row);
        if (token !== this.loadToken) return;

        if (!result) {
          row.severityState = 'error';
          return;
        }

        row.bySeverity = result.bySeverity;
        Object.assign(row, result.summary);
        row.severityState = 'loaded';
      } catch (err) {
        logger.warn(`[TestsOverviewPage] Severity load failed for ${row.service}:`, err);
        if (token === this.loadToken) {
          row.severityState = 'error';
        }
      }
    },

    toggleExpanded(row: ServiceOverviewRow): void {
      this.expandedService = this.expandedService === row.service ? null : row.service;
    },

    /** Jump from the callout chips straight to the offending row. */
    focusService(row: ServiceOverviewRow): void {
      this.search = row.displayName;
      this.statusFilter = 'all';
      this.groupFilter = [];
      this.expandedService = row.service;
    },

    navigateToDetails(serviceName: string): void {
      this.$router.push(`/tests/${serviceName}`);
    },

    statusOf(row: ServiceOverviewRow): 'critical' | 'failing' | 'passing' | 'nodata' {
      if (!row.hasData) return 'nodata';
      if (row.criticalFailed > 0) return 'critical';
      if (row.failedTests > 0) return 'failing';
      return 'passing';
    },

    /** Sort key so the Status column orders worst → best. */
    statusRank(row: ServiceOverviewRow): number {
      const ranks = { critical: 0, failing: 1, nodata: 2, passing: 3 };
      return ranks[this.statusOf(row)];
    },

    statusLabel(row: ServiceOverviewRow): string {
      const labels = {
        critical: 'Critical',
        failing: 'Failing',
        passing: 'Passing',
        nodata: 'No data',
      };
      return labels[this.statusOf(row)];
    },

    statusIcon(row: ServiceOverviewRow): string {
      const icons = {
        critical: 'bolt',
        failing: 'error',
        passing: 'check_circle',
        nodata: 'remove_circle_outline',
      };
      return icons[this.statusOf(row)];
    },

    rowClass(row: ServiceOverviewRow): string {
      const status = this.statusOf(row);
      if (status === 'critical') return 'row--critical';
      if (status === 'failing') return 'row--failing';
      if (status === 'nodata') return 'row--nodata';
      return '';
    },

    cellClass(colName: string, row: ServiceOverviewRow): string {
      if (colName === 'criticalFailed' && row.criticalFailed > 0) {
        return 'cell--critical';
      }
      return '';
    },

    skippedShare(row: ServiceOverviewRow): number {
      return row.totalTests > 0 ? (row.skippedTests / row.totalTests) * 100 : 0;
    },

    /**
     * Only flag skipped tests when they are a meaningful share of the suite —
     * a handful of environment-gated skips is normal and shouldn't paint the
     * column amber on every row.
     */
    skippedClass(row: ServiceOverviewRow): string {
      if (!row.hasData || row.skippedTests === 0) return 'text-muted';
      return this.skippedShare(row) >= SKIPPED_WARN_SHARE ? 'value-warn' : '';
    },

    passRateColor(passRate: number): string {
      if (passRate >= 99) return 'var(--success)';
      if (passRate >= 90) return 'var(--warning)';
      return 'var(--destructive)';
    },

    stalenessClass(lastRunAt: Date | null): string {
      if (!lastRunAt) return 'text-muted';
      const ageHours = (Date.now() - lastRunAt.getTime()) / 3_600_000;
      return ageHours > STALE_RUN_HOURS ? 'value-warn' : '';
    },

    formatNumber(value: number): string {
      return value.toLocaleString();
    },

    formatDateTime(value: Date): string {
      return date.formatDate(value, 'MMM D, YYYY HH:mm');
    },

    formatRelative(value: Date | null): string {
      if (!value) return 'never';
      const minutes = Math.round((Date.now() - value.getTime()) / 60_000);
      if (minutes < 1) return 'just now';
      if (minutes < 60) return `${minutes}m ago`;
      const hours = Math.round(minutes / 60);
      if (hours < 24) return `${hours}h ago`;
      const days = Math.round(hours / 24);
      return `${days}d ago`;
    },

    formatDuration(ms: number): string {
      if (ms <= 0) return '—';
      const totalSeconds = Math.round(ms / 1000);
      if (totalSeconds < 60) return `${totalSeconds}s`;
      const minutes = Math.floor(totalSeconds / 60);
      if (minutes < 60) return `${minutes}m ${totalSeconds % 60}s`;
      return `${Math.floor(minutes / 60)}h ${minutes % 60}m`;
    },
  },
});
</script>

